1	-- bipar_lote_scanner: processa um lote inteiro de containers do Scanner QR numa única chamada.
2	-- Antes o frontend fazia ~3 round-trips por caixa (SELECT estoque + RPC bipar_etiqueta + INSERT
3	-- movimentacoes); esta função troca tudo por 1 chamada por lote.
4	--
5	-- Atribuicao de usuario: chama get_usuario_id_from_auth(auth.uid()) de forma INEQUIVOCA
6	-- (a funcao tem 2 overloads — chamar sem arg dava "function is not unique") e dentro de bloco
7	-- de excecao — atribuir usuario NUNCA derruba a entrada. Antes o Scanner deixava usuario_id NULL,
8	-- entao a coluna "Responsável" da lista ficava vazia.
9	--
10	-- QTY AUTORITATIVA: quando ha uid, a quantidade vem da propria etiqueta
11	-- (quantidade_disponivel; senao quantidade_interna) — a caixa sabe quantas unidades tem.
12	-- Garante +40 (o conteudo real), nunca +1 por payload incompleto.
13	--
14	-- Cada item e' isolado em seu proprio bloco de excecao: 1 item ruim nao derruba o lote.
15	
16	CREATE OR REPLACE FUNCTION public.bipar_lote_scanner(
17	    p_loja_id integer,
18	    p_tipo text,
19	    p_itens jsonb
20	)
21	RETURNS jsonb
22	LANGUAGE plpgsql
23	SECURITY DEFINER
24	SET search_path TO 'public'
25	AS $$
26	DECLARE
27	    v_usuario_id integer;
28	    v_item jsonb;
29	    v_id text;
30	    v_pid integer;
31	    v_uid text;
32	    v_lote_id uuid;
33	    v_qty numeric;
34	    v_disp numeric;
35	    v_interna numeric;
36	    v_tipo_embalagem text;
37	    v_embalagem_nome text;
38	    v_lote text;
39	    v_payload jsonb;
40	    v_saldo_anterior numeric;
41	    v_saldo_novo numeric;
42	    v_motivo text;
43	    v_observacoes text;
44	    v_resultados jsonb := '[]'::jsonb;
45	    v_ok integer := 0;
46	    v_err integer := 0;
47	BEGIN
48	    -- Atribuicao de usuario: chamada inequivoca (1 arg) + nunca fatal.
49	    BEGIN
50	        v_usuario_id := public.get_usuario_id_from_auth(auth.uid());
51	    EXCEPTION WHEN OTHERS THEN
52	        v_usuario_id := NULL;
53	    END;
54	
55	    -- Itera NA ORDEM do array: o trigger AFTER INSERT em movimentacoes atualiza `estoque`,
56	    -- entao re-selecionar `estoque` a cada item da o saldo corrente correto na mesma transacao
57	    -- (varios containers do mesmo produto acumulam saldo na sequencia certa).
58	    FOR v_item IN SELECT * FROM jsonb_array_elements(p_itens)
59	    LOOP
60	        v_id := v_item->>'id';
61	        BEGIN
62	            v_pid := (v_item->>'pid')::integer;
63	            v_uid := NULLIF(v_item->>'uid', '');
64	            v_lote_id := NULLIF(v_item->>'lote_id', '')::uuid;
65	            v_qty := (v_item->>'qty')::numeric;
66	            v_tipo_embalagem := NULLIF(v_item->>'tipo_embalagem', '');
67	            v_embalagem_nome := NULLIF(v_item->>'embalagem_nome', '');
68	            v_lote := NULLIF(v_item->>'lote', '');
69	            v_payload := v_item->'payload';
70	
71	            -- Atualiza status da etiqueta (reaproveita RPC; backfill garante a linha existir).
72	            -- Nao mexe em estoque/movimentacoes; ok=false e' so warning; excecao nao derruba o item.
73	            IF v_uid IS NOT NULL THEN
74	                BEGIN
75	                    PERFORM public.bipar_etiqueta(
76	                        v_uid,
77	                        CASE WHEN p_tipo = 'entrada' THEN 'entrada' ELSE 'saida' END,
78	                        jsonb_build_object(
79	                            'loja_id', p_loja_id,
80	                            'referencia_tipo', 'scanner_lote',
81	                            'payload', v_payload
82	                        )
83	                    );
84	                EXCEPTION WHEN OTHERS THEN
85	                    NULL;
86	                END;
87	
88	                -- QTY AUTORITATIVA: o que a caixa realmente tem (disponivel), senao capacidade
89	                -- nominal (interna), senao o que o front mandou. Evita o bug de "+1".
90	                SELECT quantidade_disponivel, quantidade_interna
91	                  INTO v_disp, v_interna
92	                  FROM etiquetas_qr
93	                 WHERE uid = v_uid;
94	                v_qty := COALESCE(NULLIF(v_disp, 0), NULLIF(v_interna, 0), v_qty);
95	            END IF;
96	
97	            IF v_qty IS NULL OR v_qty <= 0 THEN
98	                RAISE EXCEPTION 'Container ja vazio — nada para dar saida';
99	            END IF;
100	
101	            SELECT COALESCE(quantidade_atual, 0)
102	              INTO v_saldo_anterior
103	              FROM estoque
104	             WHERE produto_master_id = v_pid
105	               AND loja_id = p_loja_id;
106	
107	            v_saldo_anterior := COALESCE(v_saldo_anterior, 0);
108	
109	            IF p_tipo = 'entrada' THEN
110	                v_saldo_novo := v_saldo_anterior + v_qty;
111	            ELSE
112	                v_saldo_novo := GREATEST(0, v_saldo_anterior - v_qty);
113	            END IF;
114	
115	            v_motivo := CASE WHEN p_tipo = 'entrada' THEN 'scanner_lote' ELSE 'saida_inteira' END;
116	            v_observacoes := (CASE WHEN p_tipo = 'entrada' THEN 'Entrada' ELSE 'Saída inteira' END)
117	                || ' via Scanner QR — ' || COALESCE(v_tipo_embalagem, 'container')
118	                || ' de ' || v_qty::text || ' ' || COALESCE(v_embalagem_nome, 'un')
119	                || ' · Lote ' || COALESCE(v_lote, '—');
120	
121	            INSERT INTO movimentacoes (
122	                produto_master_id, tipo_movimentacao, quantidade,
123	                quantidade_anterior, quantidade_nova, motivo, observacoes,
124	                data_movimentacao, loja_id, lote_id, etiqueta_qr_uid, usuario_id
125	            ) VALUES (
126	                v_pid, p_tipo, v_qty,
127	                v_saldo_anterior, v_saldo_novo, v_motivo, v_observacoes,
128	                now(), p_loja_id, v_lote_id, v_uid, v_usuario_id
129	            );
130	
131	            v_resultados := v_resultados || jsonb_build_object('id', v_id, 'ok', true);
132	            v_ok := v_ok + 1;
133	
134	        EXCEPTION WHEN OTHERS THEN
135	            v_resultados := v_resultados || jsonb_build_object('id', v_id, 'ok', false, 'erro', SQLERRM);
136	            v_err := v_err + 1;
137	        END;
138	    END LOOP;
139	
140	    RETURN jsonb_build_object(
141	        'ok', true,
142	        'processados', v_ok,
143	        'falhas', v_err,
144	        'resultados', v_resultados
145	    );
146	END;
147	$$;
148

1	-- =============================================================================
2	-- EXPOSITORA (Pronta Entrega v2) — controle do estoque exposto no salão
3	--
4	-- Modelo: estoque (câmara fria/congelado) → EXPOSITORA (vitrines/balcão) → venda.
5	-- Total em loja = estoque.quantidade_atual + expositora_estoque.quantidade.
6	--
7	-- Ponto único de integração: trigger em movimentacoes. Toda saída de estoque
8	-- com motivo da família "exposição" credita a expositora NA MESMA TRANSAÇÃO:
9	--   · 'exposicao'                 → movimentação manual (página Pronta Entrega)
10	--   · 'saida_inteira_exposicao'   → bip de container inteiro (bipar_etiqueta etapa 'exposicao')
11	--   · 'retirada_avulsa_exposicao' → retirada parcial com destino expositora
12	--
13	-- Saldo da expositora PODE ficar negativo por design — mostra o furo de
14	-- processo (venda/perda sem registro de subida pra vitrine). Fase 2 (Degust)
15	-- vai lançar tipo='venda' no ledger.
16	--
17	-- Nada destrutivo: pronta_entrega_stock/logs permanecem como histórico.
18	-- =============================================================================
19	
20	-- ─────────────────────────────────────────────────────────────────────────────
21	-- 1) Tabelas: saldo + ledger append-only
22	-- ─────────────────────────────────────────────────────────────────────────────
23	
24	CREATE TABLE IF NOT EXISTS public.expositora_estoque (
25	  id                bigserial PRIMARY KEY,
26	  produto_master_id integer NOT NULL REFERENCES public.produtos_master(id),
27	  loja_id           integer NOT NULL REFERENCES public.lojas(id),
28	  quantidade        numeric NOT NULL DEFAULT 0,  -- pode ser negativa (furo de processo visível)
29	  updated_at        timestamptz NOT NULL DEFAULT now(),
30	  UNIQUE (produto_master_id, loja_id)
31	);
32	
33	CREATE INDEX IF NOT EXISTS idx_expositora_estoque_loja
34	  ON public.expositora_estoque (loja_id);
35	
36	CREATE TABLE IF NOT EXISTS public.expositora_movimentacoes (
37	  id                bigserial PRIMARY KEY,
38	  produto_master_id integer NOT NULL REFERENCES public.produtos_master(id),
39	  loja_id           integer NOT NULL REFERENCES public.lojas(id),
40	  tipo              text    NOT NULL CHECK (tipo IN ('entrada','saida','ajuste','venda')),
41	  quantidade        numeric NOT NULL,            -- magnitude do movimento (sempre > 0)
42	  saldo_anterior    numeric NOT NULL,
43	  saldo_novo        numeric NOT NULL,
44	  motivo            text    NOT NULL,
45	  movimentacao_id   integer REFERENCES public.movimentacoes(id) ON DELETE SET NULL,
46	  etiqueta_qr_uid   text,                        -- trace; sem FK de propósito (etiquetas podem ser limpas)
47	  usuario_id        uuid,
48	  usuario_nome      text,
49	  observacoes       text,
50	  created_at        timestamptz NOT NULL DEFAULT now()
51	);
52	
53	CREATE INDEX IF NOT EXISTS idx_expositora_mov_loja_produto_data
54	  ON public.expositora_movimentacoes (loja_id, produto_master_id, created_at DESC);
55	CREATE INDEX IF NOT EXISTS idx_expositora_mov_loja_data
56	  ON public.expositora_movimentacoes (loja_id, created_at DESC);
57	
58	-- RLS: leitura pra authenticated; escrita SÓ via funções SECURITY DEFINER
59	ALTER TABLE public.expositora_estoque        ENABLE ROW LEVEL SECURITY;
60	ALTER TABLE public.expositora_movimentacoes  ENABLE ROW LEVEL SECURITY;
61	
62	DROP POLICY IF EXISTS expositora_estoque_select ON public.expositora_estoque;
63	CREATE POLICY expositora_estoque_select
64	  ON public.expositora_estoque FOR SELECT TO authenticated USING (true);
65	
66	DROP POLICY IF EXISTS expositora_movimentacoes_select ON public.expositora_movimentacoes;
67	CREATE POLICY expositora_movimentacoes_select
68	  ON public.expositora_movimentacoes FOR SELECT TO authenticated USING (true);
69	
70	-- ─────────────────────────────────────────────────────────────────────────────
71	-- 2) Nova etapa 'exposicao' no CHECK de etiquetas_qr_eventos
72	-- ─────────────────────────────────────────────────────────────────────────────
73	
74	ALTER TABLE public.etiquetas_qr_eventos
75	  DROP CONSTRAINT IF EXISTS etiquetas_qr_eventos_etapa_check;
76	ALTER TABLE public.etiquetas_qr_eventos
77	  ADD CONSTRAINT etiquetas_qr_eventos_etapa_check CHECK (etapa = ANY (ARRAY[
78	    'geracao'::text, 'separacao'::text, 'conferencia'::text, 'entrada'::text,
79	    'saida'::text, 'consumo'::text, 'descarte'::text, 'reposicao'::text,
80	    'backfill'::text, 'exposicao'::text
81	  ]));
82	
83	-- ─────────────────────────────────────────────────────────────────────────────
84	-- 3) Helper interno: aplica delta no saldo da expositora + grava ledger
85	--    (lock por linha; cria a linha zerada se não existir)
86	-- ─────────────────────────────────────────────────────────────────────────────
87	
88	CREATE OR REPLACE FUNCTION public.fn_expositora_aplicar(
89	  p_produto_master_id integer,
90	  p_loja_id           integer,
91	  p_delta             numeric,   -- positivo soma, negativo subtrai
92	  p_tipo              text,      -- 'entrada' | 'saida' | 'ajuste' | 'venda'
93	  p_motivo            text,
94	  p_movimentacao_id   integer DEFAULT NULL,
95	  p_etiqueta_qr_uid   text    DEFAULT NULL,
96	  p_usuario_id        uuid    DEFAULT NULL,
97	  p_usuario_nome      text    DEFAULT NULL,
98	  p_observacoes       text    DEFAULT NULL
99	) RETURNS numeric
100	LANGUAGE plpgsql
101	SECURITY DEFINER
102	SET search_path TO 'public'
103	AS $$
104	DECLARE
105	  v_saldo_anterior numeric;
106	  v_saldo_novo     numeric;
107	BEGIN
108	  IF p_delta IS NULL OR p_delta = 0 THEN
109	    SELECT quantidade INTO v_saldo_anterior
110	      FROM public.expositora_estoque
111	     WHERE produto_master_id = p_produto_master_id AND loja_id = p_loja_id;
112	    RETURN COALESCE(v_saldo_anterior, 0);
113	  END IF;
114	
