290	CREATE OR REPLACE FUNCTION public.ajustar_expositora(
291	  p_produto_master_id integer,
292	  p_loja_id           integer,
293	  p_quantidade        numeric,            -- delta (modo 'delta') ou saldo alvo (modo 'absoluto')
294	  p_modo              text DEFAULT 'delta',
295	  p_motivo            text DEFAULT 'outro',
296	  p_observacoes       text DEFAULT NULL
297	) RETURNS jsonb
298	LANGUAGE plpgsql
299	SECURITY DEFINER
300	SET search_path TO 'public'
301	AS $$
302	DECLARE
303	  v_user_id      uuid := auth.uid();
304	  v_user_nome    text;
305	  v_saldo_atual  numeric;
306	  v_delta        numeric;
307	  v_saldo_novo   numeric;
308	BEGIN
309	  IF p_modo NOT IN ('delta','absoluto') THEN
310	    RETURN jsonb_build_object('ok', false, 'erro', 'Modo inválido: ' || COALESCE(p_modo,'<null>'));
311	  END IF;
312	  IF p_motivo NOT IN ('perda','vencido','degustacao','consumo_interno','recontagem','contagem_inicial','outro') THEN
313	    RETURN jsonb_build_object('ok', false, 'erro', 'Motivo inválido: ' || COALESCE(p_motivo,'<null>'));
314	  END IF;
315	  IF p_quantidade IS NULL THEN
316	    RETURN jsonb_build_object('ok', false, 'erro', 'Quantidade obrigatória');
317	  END IF;
318	  IF p_loja_id IS NULL OR p_loja_id = 1 THEN
319	    RETURN jsonb_build_object('ok', false, 'erro', 'Expositora é por loja — fábrica não tem vitrine');
320	  END IF;
321	  IF NOT EXISTS (SELECT 1 FROM public.produtos_master WHERE id = p_produto_master_id) THEN
322	    RETURN jsonb_build_object('ok', false, 'erro', 'Produto não encontrado');
323	  END IF;
324	
325	  -- garante linha + trava antes de calcular delta (modo absoluto depende do saldo atual)
326	  INSERT INTO public.expositora_estoque (produto_master_id, loja_id, quantidade)
327	  VALUES (p_produto_master_id, p_loja_id, 0)
328	  ON CONFLICT (produto_master_id, loja_id) DO NOTHING;
329	
330	  SELECT quantidade INTO v_saldo_atual
331	    FROM public.expositora_estoque
332	   WHERE produto_master_id = p_produto_master_id AND loja_id = p_loja_id
333	   FOR UPDATE;
334	
335	  v_delta := CASE WHEN p_modo = 'absoluto' THEN p_quantidade - v_saldo_atual ELSE p_quantidade END;
336	
337	  IF v_delta = 0 THEN
338	    RETURN jsonb_build_object('ok', true, 'saldo', v_saldo_atual, 'delta', 0,
339	                              'mensagem', 'Saldo já estava no valor informado');
340	  END IF;
341	
342	  SELECT COALESCE(raw_user_meta_data->>'nome', email) INTO v_user_nome
343	    FROM auth.users WHERE id = v_user_id;
344	
345	  v_saldo_novo := public.fn_expositora_aplicar(
346	    p_produto_master_id, p_loja_id, v_delta,
347	    'ajuste', p_motivo, NULL, NULL,
348	    v_user_id, v_user_nome, p_observacoes
349	  );
350	
351	  RETURN jsonb_build_object('ok', true, 'saldo_anterior', v_saldo_atual,
352	                            'saldo', v_saldo_novo, 'delta', v_delta);
353	END;
354	$$;
